"schema": "\nCREATE TABLE IF NOT EXISTS accounts (\n    id INTEGER PRIMARY KEY,\n    name TEXT NOT NULL,\n    institution TEXT DEFAULT '',\n    type TEXT NOT NULL,\n    owner TEXT NOT NULL DEFAULT 'Personal',\n    opening_balance REAL NOT NULL DEFAULT 0,\n    archived INTEGER NOT NULL DEFAULT 0\n);\nCREATE TABLE IF NOT EXISTS transactions (\n    id INTEGER PRIMARY KEY,\n    account_id INTEGER NOT NULL REFERENCES accounts(id) ON DELETE CASCADE,\n    date TEXT NOT NULL,              -- YYYY-MM-DD\n    description TEXT NOT NULL,\n    amount REAL NOT NULL,            -- + money in, - money out (charges on a card are -)\n    category TEXT NOT NULL DEFAULT 'Uncategorized',\n    cat_manual INTEGER NOT NULL DEFAULT 0,\n    note TEXT DEFAULT '',\n    hash TEXT NOT NULL,\n    import_id INTEGER,\n    UNIQUE(account_id, hash)\n);\nCREATE INDEX IF NOT EXISTS ix_txn_date ON transactions(date);\nCREATE TABLE IF NOT EXISTS balance_snapshots (\n    id INTEGER PRIMARY KEY,\n    account_id INTEGER NOT NULL REFERENCES accounts(id) ON DELETE CASCADE,\n    date TEXT NOT NULL,\n    balance REAL NOT NULL            -- signed: what you owe on a card is negative\n);\nCREATE TABLE IF NOT EXISTS rules (\n    id INTEGER PRIMARY KEY,\n    pattern TEXT NOT NULL,\n    category TEXT NOT NULL,\n    owner TEXT DEFAULT NULL,         -- NULL = applies to Personal and Business\n    priority INTEGER NOT NULL DEFAULT 0   -- user rules = 10, built-in = 0\n);\nCREATE TABLE IF NOT EXISTS budgets (\n    owner TEXT NOT NULL,\n    category TEXT NOT NULL,\n    monthly_amount REAL NOT NULL,\n    PRIMARY KEY (owner, category)\n);\nCREATE TABLE IF NOT EXISTS imports (\n    id INTEGER PRIMARY KEY,\n    account_id INTEGER,\n    filename TEXT,\n    imported_at TEXT DEFAULT CURRENT_TIMESTAMP,\n    added INTEGER,\n    skipped INTEGER\n);\nCREATE TABLE IF NOT EXISTS settings (key TEXT PRIMARY KEY, value TEXT);\nCREATE TABLE IF NOT EXISTS categories (\n    name TEXT PRIMARY KEY,\n    kind TEXT NOT NULL DEFAULT 'spending'      -- spending | income | transfer (not spending)\n);\n",
